import math,itertools,numpy as np
RU_C=2.05; S=1.38; RP=S/(2*math.sin(math.radians(36)))
CN=S*math.cos(math.radians(54)); LN=S*math.sin(math.radians(54)); OU=RP+RP*math.cos(math.radians(36)); OV=RP*math.sin(math.radians(36))
def unit(x): return x/np.linalg.norm(x)
def mH(C,N):
 a=unit(N-C); ref=np.array([0.,0.,1.]);
 if abs(np.dot(a,ref))>.9: ref=np.array([1.,0.,0.])
 e1=unit(ref-np.dot(ref,a)*a); e2=unit(np.cross(a,e1))
 return [C+1.09*unit(-a/3+math.sqrt(8/9)*(math.cos(math.radians(q))*e1+math.sin(math.radians(q))*e2)) for q in (0,120,240)]
def lig(th,ph):
 th=math.radians(th); ph=math.radians(ph); u=np.array([math.cos(th),math.sin(th),0.]); v0=np.array([-math.sin(th),math.cos(th),0.]); v=math.cos(ph)*v0+math.sin(ph)*np.array([0.,0.,1.])
 C=RU_C*u; Na=C+CN*u+LN*v; Ca=C+OU*u+OV*v; Cb=C+OU*u-OV*v; Nb=C+CN*u-LN*v
 def ex(c,a,b): return -unit(unit(a-c)+unit(b-c))
 Ma=Na+1.46*ex(Na,C,Ca); Mb=Nb+1.46*ex(Nb,C,Cb); Ha=Ca+1.08*ex(Ca,Na,Cb); Hb=Cb+1.08*ex(Cb,Ca,Nb)
 return np.array([C,Na,Ca,Ha,Cb,Hb,Nb,Ma,*mH(Ma,Na),Mb,*mH(Mb,Nb)])
angs=[135,45,-45,-135]; opts=[-90,-60,-45,-30,0,30,45,60,90]
L={(i,t):lig(a,t) for i,a in enumerate(angs) for t in opts}
paird={}
for i in range(4):
 for j in range(i):
  for ti in opts:
   for tj in opts:
    d=np.sqrt(((L[i,ti][:,None,:]-L[j,tj][None,:,:])**2).sum(-1)).min()
    paird[i,j,ti,tj]=d
ax={ (i,t):np.sqrt(((L[i,t][:,None,:]-np.array([[0,0,1.6],[0,0,-1.6]]))**2).sum(-1)).min() for i in range(4) for t in opts}
b=[]
for ts in itertools.product(opts,repeat=4):
 md=min(paird[i,j,ts[i],ts[j]] for i in range(4) for j in range(i))
 ad=min(ax[i,ts[i]] for i in range(4))
 b.append((min(md,ad),md,ad,ts))
for x in sorted(b,reverse=True)[:20]: print(x)
